si_points = []
for t_sbp, v_sbp in systolic_bp:
    closest_hr = None
    min_diff = 300.0
    for t_hr, v_hr in heart_rate:
        diff = abs((t_hr - t_sbp).total_seconds())
        if diff < min_diff:
            min_diff = diff
            closest_hr = v_hr
    if closest_hr is not None and v_sbp > 0:
        si = closest_hr / v_sbp
        si_points.append((t_sbp, si))
si_points.sort(key=lambda x: x[0])
times = [p[0] for p in si_points]
values = [p[1] for p in si_points]
if values:
    si_array = np.array(values)
    mean_si = np.mean(si_array)
    max_si = np.max(si_array)
    pct_critical = np.mean(si_array >= 1.0) * 100.0
    fig, ax = plt.subplots(figsize=(10, 6))
    start_time = times[0]
    rel_hours = [(t - start_time).total_seconds() / 3600.0 for t in times]
    ax.plot(rel_hours, values, 'o-', color='#800080', linewidth=2, markersize=5, label='Shock Index')
    ax.axhspan(0.5, 0.7, color='green', alpha=0.1, label='Intervallo Normale (0.5-0.7)')
    ax.axhline(1.0, color='red', linestyle='--', linewidth=2, label='Soglia Critica (1.0)')
    ax.set_title('Analisi Trend Shock Index (HR / SBP)', fontsize=12, fontweight='bold')
    ax.set_xlabel('Tempo (Ore dall\'ammissione)')
    ax.set_ylabel('Shock Index')
    ax.legend(loc='upper left')
    ax.grid(True, linestyle=':', alpha=0.6)
    max_idx = np.argmax(si_array)
    ax.annotate(f'Max: {max_si:.2f}', xy=(rel_hours[max_idx], values[max_idx]), xytext=(rel_hours[max_idx], values[max_idx] + 0.2), arrowprops=dict(facecolor='black', shrink=0.05))
    save_plot('shock_index_trend.png', fig)
    if mean_si > 0.9:
        status = 'SOSTENUTA ELEVAZIONE'
        context = 'indicando instabilità emodinamica persistente e stato di shock scompensato'
    elif max_si > 1.0:
        status = 'INSTABILITÀ TRANSITORIA'
